package com.bank.deps.ops;

import com.bank.deps.model.Txn;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Narrow dependency: each parent partition → exactly one child partition.
public class NarrowOps {
    private static final Logger log = Logger.getLogger(NarrowOps.class.getName());

    // map/filter style: transform each partition independently, NO shuffle.
    public List<List<String>> mapStamp(List<List<Txn>> partitions) {
        log.info("NARROW map: each partition processed in place — 0 records shuffled");
        List<List<String>> out = new ArrayList<>();
        for (List<Txn> part : partitions) {
            List<String> stamped = new ArrayList<>();
            for (Txn t : part) {
                stamped.add(t.getAccountId() + ":" + t.getAmount() + ":PROCESSED");
            }
            out.add(stamped); // 1 parent partition -> 1 child partition
        }
        return out;
    }
}
