package com.bank.deps.ops;

import com.bank.deps.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Wide dependency: one parent partition feeds many children — SHUFFLE.
public class WideOps {
    private static final Logger log = Logger.getLogger(WideOps.class.getName());

    // groupByKey: ships EVERY value across the network before grouping.
    public Map<String, BigDecimal> groupByKey(List<List<Txn>> partitions) {
        int shuffled = 0;
        Map<String, List<BigDecimal>> grouped = new HashMap<>();
        for (List<Txn> part : partitions) {
            for (Txn t : part) {
                grouped.computeIfAbsent(t.getAccountId(), k -> new ArrayList<>())
                       .add(t.getAmount());
                shuffled++; // every single value crosses the shuffle
            }
        }
        final int moved = shuffled;
        log.warning(() -> "WIDE groupByKey: shuffled " + moved + " records across the network");
        Map<String, BigDecimal> totals = new HashMap<>();
        grouped.forEach((k, vs) -> {
            BigDecimal sum = BigDecimal.ZERO;
            for (BigDecimal v : vs) sum = sum.add(v);
            totals.put(k, sum);
        });
        return totals;
    }

    // reduceByKey: combines locally per partition FIRST, then shuffles partials.
    public Map<String, BigDecimal> reduceByKey(List<List<Txn>> partitions) {
        int shuffled = 0;
        Map<String, BigDecimal> totals = new HashMap<>();
        for (List<Txn> part : partitions) {
            // map-side combine: one partial per key per partition
            Map<String, BigDecimal> local = new HashMap<>();
            for (Txn t : part) {
                local.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
            }
            // only the partials cross the shuffle
            for (Map.Entry<String, BigDecimal> e : local.entrySet()) {
                totals.merge(e.getKey(), e.getValue(), BigDecimal::add);
                shuffled++;
            }
        }
        final int moved = shuffled;
        log.info(() -> "WIDE reduceByKey: shuffled only " + moved + " partial records (map-side combine)");
        return totals;
    }
}
