package com.bank.deps;

import com.bank.deps.model.Txn;
import com.bank.deps.ops.NarrowOps;
import com.bank.deps.ops.WideOps;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class DepsDemo {
    private static final Logger log = Logger.getLogger(DepsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new DepsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // 2 partitions, Rajesh and Priya transactions scattered across both.
        List<List<Txn>> partitions = List.of(
            List.of(new Txn("SAV2001", new BigDecimal("1000")),
                    new Txn("CUR3001", new BigDecimal("500")),
                    new Txn("SAV2001", new BigDecimal("2000"))),
            List.of(new Txn("SAV2001", new BigDecimal("3000")),
                    new Txn("CUR3001", new BigDecimal("700")))
        );

        NarrowOps narrow = new NarrowOps();
        narrow.mapStamp(partitions); // no shuffle

        WideOps wide = new WideOps();
        var g = wide.groupByKey(partitions);   // shuffles 5 records
        log.info(() -> "groupByKey totals = " + g);

        var r = wide.reduceByKey(partitions);  // shuffles only 4 partials
        log.info(() -> "reduceByKey totals = " + r);
    }
}

